import * as fs from 'node:fs';
import * as events from 'node:events';
import * as util from 'node:util';
import * as os from 'node:os';
import * as path from 'node:path';
const all: any = { fs, events, util, os, path };
function main(): void {
  for (const k of Object.keys(all)) console.log(k, typeof all[k].default, Object.keys(all[k]).includes('default'), Object.prototype.toString.call(all[k]));
}
